-- =========================================================================
-- MIGRATION SCRIPT: MAIL TEMPLATES FOR DEMO_P_FLOW (POLICYISSUANCE)
-- =========================================================================
BEGIN TRANSACTION;
BEGIN TRY
    -- 1. Insert mail templates if not exists
    DECLARE @InitiatedId BIGINT, @FollowUpId BIGINT, @SignedId BIGINT, @PreCompleteId BIGINT;

    IF NOT EXISTS (SELECT 1 FROM MailTemplate WHERE TemplateName = 'PolicyIssuanceInitiated' AND Deleted = 0)
    BEGIN
        INSERT INTO MailTemplate (TemplateName, TemplateContent, Guid, CreatedBy, CreatedDate, Deleted, RowOrder, PrefixTitleMail, TemplateMailTitle, MailQuery, IsActive)
        VALUES ('PolicyIssuanceInitiated', N'<p>Dear @@RecipientName,</p><p>A new Policy Issuance request has been initiated.</p><p><strong>Policy Issuance ID:</strong> @@PolicyIssuanceId<br><strong>Client:</strong> @@ShortName<br><strong>Initiated by:</strong> @@MakerName</p><p>Please review and proceed with the technical survey.</p><p><a href=''@@urlCallView'' style=''color: #337ab7;''>Click here to view Policy Issuance</a></p>', NEWID(), 'quan.nh', GETDATE(), 0, 100, N'[Policy Issuance Initiated]', N'- Policy Issuance #@@PolicyIssuanceId - @@ShortName', N'SELECT TOP 1 N''Policy Issuance Initiated'' AS MailType, u2.name AS RecipientName, u2.email AS RecipientEmail, u1.name AS MakerName, ISNULL(c.ShortName, '''') AS ShortName, p.Id AS PolicyIssuanceId, p.* FROM PolicyIssuance p INNER JOIN InstanceWorkflow i ON p.Guid = i.RecordGuid INNER JOIN UserWorkflow uf ON uf.Id = i.UserWorkflowId LEFT JOIN Users u1 ON p.CreatedBy = u1.username LEFT JOIN Users u2 ON uf.CheckerUsersId = u2.Id LEFT JOIN Client c ON c.Id = p.ClientId ORDER BY i.CreatedDate DESC', 1);
    END
    SELECT @InitiatedId = Id FROM MailTemplate WHERE TemplateName = 'PolicyIssuanceInitiated' AND Deleted = 0;

    IF NOT EXISTS (SELECT 1 FROM MailTemplate WHERE TemplateName = 'PolicyIssuancePMFollowUp' AND Deleted = 0)
    BEGIN
        INSERT INTO MailTemplate (TemplateName, TemplateContent, Guid, CreatedBy, CreatedDate, Deleted, RowOrder, PrefixTitleMail, TemplateMailTitle, MailQuery, IsActive)
        VALUES ('PolicyIssuancePMFollowUp', N'<p>Dear Team,</p><p>The Project Manager has requested a document follow-up for this Policy Issuance.</p><p><strong>Policy Issuance ID:</strong> @@PolicyIssuanceId<br><strong>Client:</strong> @@ShortName<br><strong>Remarks:</strong> @@Comment</p><p>Please check the required document and sign back.</p><p><a href=''@@urlCallView'' style=''color: #337ab7;''>Click here to view Policy Issuance</a></p>', NEWID(), 'quan.nh', GETDATE(), 0, 100, N'[Policy Issuance Follow Up]', N'- Policy Issuance #@@PolicyIssuanceId - @@ShortName', N'SELECT TOP 1 N''Policy Issuance PM Follow Up'' AS MailType, u2.name AS RecipientName, u2.email AS RecipientEmail, u1.name AS MakerName, ISNULL(c.ShortName, '''') AS ShortName, ISNULL(i.Comment, '''') AS Comment, p.Id AS PolicyIssuanceId, p.* FROM PolicyIssuance p INNER JOIN InstanceWorkflow i ON p.Guid = i.RecordGuid INNER JOIN UserWorkflow uf ON uf.Id = i.UserWorkflowId LEFT JOIN Users u1 ON p.CreatedBy = u1.username LEFT JOIN Users u2 ON uf.CheckerUsersId = u2.Id LEFT JOIN Client c ON c.Id = p.ClientId ORDER BY i.CreatedDate DESC', 1);
    END
    SELECT @FollowUpId = Id FROM MailTemplate WHERE TemplateName = 'PolicyIssuancePMFollowUp' AND Deleted = 0;

    IF NOT EXISTS (SELECT 1 FROM MailTemplate WHERE TemplateName = 'PolicyIssuanceClientSigned' AND Deleted = 0)
    BEGIN
        INSERT INTO MailTemplate (TemplateName, TemplateContent, Guid, CreatedBy, CreatedDate, Deleted, RowOrder, PrefixTitleMail, TemplateMailTitle, MailQuery, IsActive)
        VALUES ('PolicyIssuanceClientSigned', N'<p>Dear Project Manager,</p><p>The client has signed and returned the contract. Documents have been uploaded by FO/TS.</p><p><strong>Policy Issuance ID:</strong> @@PolicyIssuanceId<br><strong>Client:</strong> @@ShortName<br><strong>Submitted by:</strong> @@MakerName</p><p>Please review and complete the task.</p><p><a href=''@@urlCallView'' style=''color: #337ab7;''>Click here to view Policy Issuance</a></p>', NEWID(), 'quan.nh', GETDATE(), 0, 100, N'[Client Signed & Returned]', N'- Policy Issuance #@@PolicyIssuanceId - @@ShortName', N'SELECT TOP 1 N''Policy Issuance Client Signed'' AS MailType, u2.name AS RecipientName, u2.email AS RecipientEmail, u1.name AS MakerName, ISNULL(c.ShortName, '''') AS ShortName, p.Id AS PolicyIssuanceId, p.* FROM PolicyIssuance p INNER JOIN InstanceWorkflow i ON p.Guid = i.RecordGuid INNER JOIN UserWorkflow uf ON uf.Id = i.UserWorkflowId LEFT JOIN Users u1 ON p.CreatedBy = u1.username LEFT JOIN Users u2 ON uf.CheckerUsersId = u2.Id LEFT JOIN Client c ON c.Id = p.ClientId ORDER BY i.CreatedDate DESC', 1);
    END
    SELECT @SignedId = Id FROM MailTemplate WHERE TemplateName = 'PolicyIssuanceClientSigned' AND Deleted = 0;

    IF NOT EXISTS (SELECT 1 FROM MailTemplate WHERE TemplateName = 'PolicyIssuancePreComplete' AND Deleted = 0)
    BEGIN
        INSERT INTO MailTemplate (TemplateName, TemplateContent, Guid, CreatedBy, CreatedDate, Deleted, RowOrder, PrefixTitleMail, TemplateMailTitle, MailQuery, IsActive)
        VALUES ('PolicyIssuancePreComplete', N'<p>Dear Team,</p><p>Policy Issuance is ready for completion.</p><p><strong>Policy Issuance ID:</strong> @@PolicyIssuanceId<br><strong>Client:</strong> @@ShortName</p><p>The task is transferring back to PM for final task completion.</p><p><a href=''@@urlCallView'' style=''color: #337ab7;''>Click here to view Policy Issuance</a></p>', NEWID(), 'quan.nh', GETDATE(), 0, 100, N'[Before PM Complete Task]', N'- Policy Issuance #@@PolicyIssuanceId - @@ShortName', N'SELECT TOP 1 N''Policy Issuance Pre-Complete'' AS MailType, u2.name AS RecipientName, u2.email AS RecipientEmail, u1.name AS MakerName, ISNULL(c.ShortName, '''') AS ShortName, p.Id AS PolicyIssuanceId, p.* FROM PolicyIssuance p INNER JOIN InstanceWorkflow i ON p.Guid = i.RecordGuid INNER JOIN UserWorkflow uf ON uf.Id = i.UserWorkflowId LEFT JOIN Users u1 ON p.CreatedBy = u1.username LEFT JOIN Users u2 ON uf.CheckerUsersId = u2.Id LEFT JOIN Client c ON c.Id = p.ClientId ORDER BY i.CreatedDate DESC', 1);
    END
    SELECT @PreCompleteId = Id FROM MailTemplate WHERE TemplateName = 'PolicyIssuancePreComplete' AND Deleted = 0;

    -- 2. Update JSON in WorkflowDefinition
    UPDATE WorkflowDefinition 
    SET WorkflowNodes = '{"_layoutConfig":null,"workflowDefinition":{},"lanes":[],"workflowNodes":[{"id":"NODE_1784254897806","laneId":"","nodeName":"Start Node","nodeType":"start","nodeCode":"NODE_1784254897806","code":"NODE_1784254897806","flowType":"Both","stepRole":"","levelNo":1,"allowLoop":false,"loopGroup":"","shape":"circle","styleColor":"green","posX":-108,"posY":-47,"x":-108,"y":-47,"assignLabel":"","orderLabel":"","departmentName":"","description":"Initial workflow step","sortOrder":1,"orderNo":1,"screenConditions":[],"custom":""},{"id":"NODE_1784254897807","laneId":"","nodeName":"FO","nodeType":"department","nodeCode":"FO","code":"FO","flowType":"PolicyIssuance","stepRole":"1","levelNo":1,"allowLoop":false,"loopGroup":"","shape":"rectangle","styleColor":"blue","posX":32,"posY":-218,"x":32,"y":-218,"assignLabel":"","orderLabel":"","departmentName":"FO","description":"","sortOrder":2,"orderNo":2,"screenConditions":[],"custom":""},{"id":"NODE_1784254897808","laneId":"","nodeName":"TS","nodeType":"department","nodeCode":"TS","code":"TS","flowType":"PolicyIssuance","stepRole":"2","levelNo":1,"allowLoop":false,"loopGroup":"","shape":"rectangle","styleColor":"blue","posX":112,"posY":488,"x":112,"y":488,"assignLabel":"","orderLabel":"","departmentName":"TS","description":"","sortOrder":3,"orderNo":3,"screenConditions":[],"custom":""},{"id":"NODE_1784254897809","laneId":"","nodeName":"PM","nodeType":"department","nodeCode":"PM","code":"PM","flowType":"PolicyIssuance","stepRole":"3","levelNo":1,"allowLoop":false,"loopGroup":"","shape":"rectangle","styleColor":"blue","posX":421,"posY":-155,"x":421,"y":-155,"assignLabel":"","orderLabel":"","departmentName":"PM","description":"","sortOrder":4,"orderNo":4,"screenConditions":[],"custom":""},{"id":"NODE_1784254897810","laneId":"","nodeName":"FO","nodeType":"department","nodeCode":"FO","code":"FO","flowType":"PolicyIssuance","stepRole":"1","levelNo":1,"allowLoop":false,"loopGroup":"","shape":"rectangle","styleColor":"blu