sState":{"rootOperator":"AND","rules":[]},"isExitTransition":false,"isReturn":false,"statusId":198,"statusName":"PM Pending","icon":"","buttonClass":"","command":"None","commandConfig":"","mailTemplateId":33,"notificationTemplateId":4,"data":{"transitionScript":"","icon":"","buttonClass":"","mailTemplateId":33,"notificationTemplateId":4,"custom":""},"controlX":null,"controlY":null,"sortOrder":8},{"fromNodeId":"NODE_1784254897811","toNodeId":"NODE_1784254897813","actionName":"Complete Task","actionCode":"COMPLETE","stepNo":5,"jumpStepNo":null,"transitionType":"Normal","conditionJson":{},"conditionRulesState":{"rootOperator":"AND","rules":[]},"isExitTransition":false,"isReturn":false,"statusId":184,"statusName":"Completed","icon":"","buttonClass":"","command":"None","commandConfig":"","mailTemplateId":null,"notificationTemplateId":9,"data":{"transitionScript":"","icon":"","buttonClass":"","mailTemplateId":null,"notificationTemplateId":9,"custom":""},"controlX":null,"controlY":null,"sortOrder":9},{"fromNodeId":"NODE_1784254897812","toNodeId":"NODE_1784254897811","actionName":"Client Signed \u0026 Return","actionCode":"TS_SUBMIT_PM","stepNo":4,"jumpStepNo":null,"transitionType":"Normal","conditionJson":{},"conditionRulesState":{"rootOperator":"AND","rules":[]},"isExitTransition":false,"isReturn":false,"statusId":198,"statusName":"PM Pending","icon":"","buttonClass":"","command":"None","commandConfig":"","mailTemplateId":34,"notificationTemplateId":4,"data":{"transitionScript":"","icon":"","buttonClass":"","mailTemplateId":34,"notificationTemplateId":4,"custom":""},"controlX":null,"controlY":null,"sortOrder":10}]}'
    WHERE WorkflowCode = 'DEMO_P_FLOW';

    -- 3. Update StepsWorkflow transitions Data column
    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(ISNULL(Data, '{}'), '$.mailTemplateId', @InitiatedId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_TO_TS' AND FromNodeId = 'FO' AND ToNodeId = 'TS';

    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(ISNULL(Data, '{}'), '$.mailTemplateId', @FollowUpId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_FOLLOWUP' AND FromNodeId = 'PM' AND ToNodeId = 'FO';

    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(ISNULL(Data, '{}'), '$.mailTemplateId', @FollowUpId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'SUBMIT_FOLLOWUP' AND FromNodeId = 'PM' AND ToNodeId = 'TS';

    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(ISNULL(Data, '{}'), '$.mailTemplateId', @SignedId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'FO_SUBMIT_PM' AND FromNodeId = 'FO' AND ToNodeId = 'PM';

    UPDATE StepsWorkflow 
    SET Data = JSON_MODIFY(ISNULL(Data, '{}'), '$.mailTemplateId', @PreCompleteId)
    WHERE WorkflowDefinitionId = '38f2b0a5-3c03-47ec-ab48-4ad3d1703e0a' AND ActionCode = 'TS_SUBMIT_PM' AND FromNodeId = 'TS' AND ToNodeId = 'PM';

    COMMIT TRANSACTION;
    PRINT 'Transaction committed successfully. DEMO_P_FLOW updated! âœ…';
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
    PRINT 'Error occurred, transaction rolled back. âŒ';
    THROW;
END CATCH